'use strict';
function accountName(){return state.user?.user_metadata?.name||state.user?.user_metadata?.display_name||'Explorer'}
function spaceTabs(active){return `<div class="wrap"><nav class="tabs space-tabs" aria-label="Your account"><a class="tab ${active==='space'?'active':''}" href="#/space">Connections</a><a class="tab ${active==='progress'?'active':''}" href="#/progress">My progress</a><a class="tab ${active==='profile'?'active':''}" href="#/profile">My profile</a></nav></div>`}
function signInPage(){return pageTop('YOUR TREKSOR SPACE','One account.<br>Your whole journey.','Use your Treksor app account to see your profile, progress and community connections.')+`<section class="section"><div class="wrap">${empty('Your journey stays with you.','Sign in with the same email and password you use in the app. Your progress is private.',btn('Sign in with Treksor ↗','login'),'shield')}</div></section>`}
async function freshUser(){const id=state.user?.id;const {data,error}=await db.auth.getUser();if(error)throw error;if(state.user?.id===id&&data.user?.id===id)state.user=data.user}
async function renderProfile(version){if(!state.user){main.innerHTML=signInPage();return}await freshUser();if(version!==state.routeVersion)return;const u=state.user,metadata=u.user_metadata||{};main.innerHTML=pageTop('MY PROFILE','One profile.<br>Every part of Treksor.','Your name and photo are shared with the app. Community visibility is always your choice.')+spaceTabs('profile')+`<section class="dashboard"><div class="wrap profile-layout"><aside class="profile-panel">${avatar(accountName(),true,metadata.avatar_url)}<h3>${esc(accountName())}</h3><p class="break-anywhere">${esc(u.email)}</p><div class="spaced"><span class="tag">${u.email_confirmed_at?'Email verified':'Email awaiting confirmation'}</span></div><p class="helper spaced">Joined ${new Date(u.created_at).toLocaleDateString('en-AU',{year:'numeric',month:'long'})}</p>${btn('Sign out','logout','','ghost')}</aside><div><form id="account-form" class="detail-panel form-grid"><div class="eyebrow">APP & WEB PROFILE</div><h2>Make it yours.</h2><label>Your name<input name="name" value="${esc(accountName())}" required minlength="2" maxlength="60" autocomplete="name"></label><label>Profile photo<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="helper">JPG, PNG or WebP, up to 5 MB. Changes appear in the app when it reconnects.</p><label>Email<input value="${esc(u.email)}" disabled type="email"></label><p class="helper">This is the same account used in the Treksor app. Manage sign-in details from the app.</p><div class="form-error" role="alert"></div><button type="submit" class="button">Save app & web profile ↗</button></form><div class="detail-panel"><div class="eyebrow">YOUR COMMUNITY PRESENCE</div><h3>Choose how you connect.</h3><p>${state.profile?`Public name: ${esc(state.profile.display_name)}. ${state.profile.discoverable?'Your profile is visible in One-to-one.':'Your profile is hidden from One-to-one.'}`:'Set up a community nickname, city, interests and preferred pace.'}</p><p class="helper spaced">Your progress and sign-in email are never included in your community profile.</p><div class="spaced">${btn('Edit community preferences ↗','profile','','ghost')}</div></div><div class="detail-panel"><h3>Your training profile</h3><p>Training preferences and physical details saved in the app are available with your progress.</p><a class="text-link spaced" href="#/progress">View synced training profile ↗</a></div></div></div></section>`}
function count(v){return Math.max(0,Number(v)||0)}
function metric(title,value,note){return `<article class="metric"><span>${title}</span><strong>${esc(value)}</strong><small>${note}</small></article>`}
function dayKey(value){const d=new Date(value);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function trendChart(checkIns,days){const dates=[];for(let i=days-1;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);dates.push(d)}const counts=new Map();checkIns.forEach(v=>{const key=dayKey(v);counts.set(key,(counts.get(key)||0)+1)});const vals=dates.map(d=>counts.get(dayKey(d))||0);const max=Math.max(1,...vals);const width=760,height=160,step=width/days;return `<div class="trend-chart"><svg viewBox="0 0 760 185" role="img" aria-label="${days}-day training check-in chart. ${vals.reduce((a,b)=>a+b,0)} check-ins in this period."><line x1="0" y1="160" x2="760" y2="160" stroke="#29343e"/>${vals.map((v,i)=>`<rect x="${(i*step+2).toFixed(2)}" y="${height-v/max*135}" width="${Math.max(2,step-4)}" height="${v?Math.max(4,v/max*135):2}" rx="2" fill="${v?'#d7b877':'#26323e'}"><title>${dates[i].toLocaleDateString('en-AU')}: ${v} check-ins</title></rect>`).join('')}</svg><div class="trend-axis"><span>${dates[0].toLocaleDateString('en-AU',{day:'numeric',month:'short'})}</span><span>Today</span></div></div>`}
function pillarProgress(data){return [{...pillarData[0],keys:['body','physical','fitness','workout','exercise']},{...pillarData[1],keys:['mind','mental','journal','mood']},{...pillarData[2],keys:['balance','spiritual','meditation','recovery']},{...pillarData[3],keys:['purpose','habit','goal','vision']}].map(p=>{const matches=(data.trackers||[]).filter(t=>p.keys.some(k=>String(t.title).toLowerCase().includes(k)));const pct=matches.length?Math.round(matches.reduce((s,t)=>s+Math.max(0,Math.min(100,Number(t.percentage)||0)),0)/matches.length):null;return `<article class="progress-pillar"><div class="progress-pillar-head">${icon(p.icon)}<h3>${p.name}</h3></div><strong>${pct===null?'—':pct+'%'}</strong><div class="progress-track" role="${pct===null?'presentation':'progressbar'}" ${pct===null?'':`aria-label="${p.name} progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"`}><i style="width:${pct||0}%"></i></div><p>${pct===null?'No pillar score recorded yet':'The same score shown in your app'}</p></article>`}).join('')}
async function renderProgress(version){if(!state.user){main.innerHTML=signInPage();return}const id=state.user.id;const rows=await query(db.from('app_progress').select('device_id,payload,updated_at').eq('user_id',id).order('updated_at',{ascending:false}));if(version!==state.routeVersion||state.user?.id!==id)return;const top=pageTop('MY PROGRESS','Every step counts.','Your app journey, brought together. Visible only to you.',btn('Refresh progress ↻','refresh-progress','','ghost'))+spaceTabs('progress');if(!rows.length){main.innerHTML=top+`<section class="section"><div class="wrap">${empty('Your first sync starts in the app.','Open the updated Treksor app, sign in with this same email and visit Tracking → Sync now. Your saved training and progress will appear here after the first successful sync.',`<div class="sync-account">${esc(state.user.email)}</div><div class="inline-actions">${btn('Check again ↻','refresh-progress','','ghost')}<a class="text-link" href="#/profile">View my profile ↗</a></div>`,'compass')}<div class="info-strip">${icon('shield')}<span>Progress saved only on your phone cannot appear here until the app syncs it. Private journal text stays on your device.</span></div></div></section>`;return}const row=rows.find(r=>r.device_id===state.device)||rows[0];state.device=row.device_id;const p=row.payload;if(p.version!==1)fail('This progress format needs a website update. Please try again later.');const checkins=Object.values(p.checkIns||{}).flat().filter(v=>typeof v==='string');const sets=Array.isArray(p.gymSets)?p.gymSets:[];const recent=sets.slice().sort((a,b)=>String(b.recordedAt).localeCompare(String(a.recordedAt))).slice(0,12);const custom=(p.trackers||[]).filter(t=>t.custom&&!['BODY','MIND','SPIRITUAL','BALANCE','PURPOSE','ARTICLES'].includes(t.title.toUpperCase()));const plan=p.trainingPlan;const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-state.period+1);const inPeriod=checkins.filter(d=>new Date(d)>=cutoff&&new Date(d)<=new Date()).length;
main.innerHTML=top+`<section class="dashboard"><div class="wrap"><div class="sync-bar"><div><span class="sync-label"><i class="status-dot"></i> Synced from ${esc(p.device||'the app')}</span><p>Last synced ${date(row.updated_at)} · ${esc(state.user.email)}</p></div>${rows.length>1?`<label>Device<select id="device-select">${rows.map((r,i)=>`<option value="${esc(r.device_id)}" ${r.device_id===row.device_id?'selected':''}>${esc(r.payload.device||'Device')} ${i+1} · ${date(r.updated_at)}</option>`).join('')}</select></label>`:'<span class="tag">Private to you</span>'}</div>${rows.length>1?'<p class="helper spaced">Each device has its own history. Select a device to see its progress; totals are not combined or double-counted.</p>':''}<div class="progress-pillars">${pillarProgress(p)}</div><div class="metrics">${metric('Training check-ins',checkins.length,'All recorded check-ins on this device')}${metric('Sets logged',sets.length,'Your recorded training sets')}${metric('Articles completed',`${count(p.articles?.completed)} / ${count(p.articles?.total)}`,'Across articles loaded in your app')}${metric('Meditations completed',`${count(p.meditations?.completed)} / ${count(p.meditations?.total)}`,'Your completed sessions')}</div><div class="progress-layout"><div><section class="detail-panel"><div class="dash-title"><div><div class="eyebrow">SHOWING UP FOR YOURSELF</div><h2>Your training rhythm.</h2></div><select id="period-select" aria-label="Training chart period">${[7,30,90].map(n=>`<option value="${n}" ${n===state.period?'selected':''}>Last ${n} days</option>`).join('')}</select></div><p>${inPeriod} training check-ins in this period. Each bar is one day.</p>${trendChart(checkins,state.period)}${inPeriod?'':'<p class="helper">No check-ins recorded in this period. Log one in the app when you train.</p>'}<details class="chart-data"><summary>View check-in dates</summary>${checkins.filter(d=>new Date(d)>=cutoff).sort().reverse().map(d=>`<p>${date(d)}</p>`).join('')||'<p>No check-ins in this period.</p>'}</details></section><section class="detail-panel"><div class="dash-title"><h3>Recent training sets</h3><span class="tag">Latest 12</span></div>${recent.length?`<div class="table-scroll"><table class="progress-table"><thead><tr><th>Exercise</th><th>Weight</th><th>Reps</th><th>Recorded</th></tr></thead><tbody>${recent.map(s=>`<tr><td>${esc(s.exerciseName)}</td><td>${count(s.kg)} kg</td><td>${count(s.reps)}</td><td>${date(s.recordedAt)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No sets logged yet. Add your weights and reps in the app to see them here.</p>'}</section><section class="detail-panel"><h3>Learning & reflection</h3><p>${count(p.exercises?.completed)} of ${count(p.exercises?.total)} exercises completed · ${count(p.thoughtDates?.length)} thought-reading records</p><details class="chart-data"><summary>Completed articles (${count(p.articles?.completed)})</summary>${(p.articles?.read||[]).map(a=>`<p><span class="tag">${esc(a.category)}</span> ${esc(a.title)}</p>`).join('')||'<p>No completed articles recorded yet.</p>'}</details><p class="helper spaced">Reading records store the most recent reading day for each thought, not a complete daily reading history.</p></section><section class="detail-panel"><h3>Your custom trackers</h3>${custom.length?custom.map(t=>`<div class="tracker-row"><h4>${esc(t.title)}</h4>${(t.items||[]).map(i=>`<div class="list-row"><span>${esc(i.label)}</span><strong>${esc(i.value)}</strong><small>${Object.values(i.record||{}).filter(Boolean).length} days logged</small></div>`).join('')}</div>`).join(''):'<p>Create a custom tracker in the app to follow what matters to you.</p>'}</section></div><aside><section class="detail-panel"><div class="eyebrow">YOUR TRAINING PROFILE</div><h3>${plan?'A plan with intention.':'Your plan starts with you.'}</h3>${plan?`<dl class="profile-facts">${[['Days per week',plan.days],['Location',plan.location],['Goal',plan.goal],['Experience',plan.experience],['Age',plan.age],['Height',plan.heightCm?plan.heightCm+' cm':null],['Weight',plan.weightKg?plan.weightKg+' kg':null]].filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="helper">Saved ${date(plan.savedAt)}. Update this plan in the app.</p>`:'<p>Set up a training plan in the app. Your preferences will appear after syncing.</p>'}</section><section class="detail-panel"><div class="eyebrow">PURPOSE</div><h3>Your vision, taking shape.</h3><p class="progress-number">${count(p.vision?.completed)} <span>/ ${count(p.vision?.total)||10}</span></p><p>Vision-board prompts completed. Your written answers stay on your device.</p></section><section class="detail-panel"><h3>Keep the momentum.</h3><p>Find someone to share the next step with. Your progress remains private.</p><a class="text-link spaced" href="#/community/one-to-one">Find a companion ↗</a><a class="text-link spaced" href="#/community/mentors">Connect with a mentor ↗</a></section></aside></div><div class="info-strip">${icon('shield')}<span>Updated automatically while the app is open and online. Check the timestamp above for freshness. Your private journal is kept on your device.</span></div></div></section>`}
